\title{Tensor Amplification and Spectral Transfer for Sidorenko-Type Inequalities}
\author{Aristotle}
\date{July 9, 2026}

\begin{document}

\begin{abstract}
We develop a \emph{tensor-amplification framework} for Sidorenko-type inequalities in
the setting of weighted graphs---finite graphons represented by symmetric real matrices
with the uniform (counting) measure. The framework rests on a single algebraic identity,
\emph{spectral transfer}, which states that closed-walk counts are multiplicative under
the tensor (Kronecker) product: $\tr\big((A\otimes B)^k\big) = \tr(A^k)\,\tr(B^k)$. From
this identity we derive that all homomorphism densities, and hence the Sidorenko ratio
$R(A) = t(C_k,A)/t(K_2,A)^k$, are multiplicative under tensoring. Two transfer principles
follow immediately: (I) the class of weighted graphs satisfying the Sidorenko property for
a cycle $C_k$ is closed under tensor products; and (II) self-tensoring squares the
Sidorenko ratio, so that under iterated self-tensoring the ratio behaves as a discrete
dynamical system with exactly two fixed points, $0$ and $1$, repelling strict surpluses to
$+\infty$ and attracting strict deficits to $0$. To make the framework non-vacuous we
supply two analytic seeds---the even cycles $C_2$ and $C_4$---proving $t(C_2,A)\ge
t(K_2,A)^2$ and $t(C_4,A)\ge t(K_2,A)^4$ for \emph{every symmetric weighted graph}, with
\textbf{no positivity hypothesis} on the entries. Both proofs are pure spectral
Cauchy--Schwarz arguments organizing closed-walk counts as sums of squares. Combined with
Transfer Principle~I for even cycles, the seeds generate an entire tensor-closed class of
weighted graphs satisfying the even-cycle Sidorenko inequality, again with no sign
restriction.
\end{abstract}

\maketitle

\section{Introduction}

Sidorenko's conjecture is one of the central open problems in extremal graph theory. In its
density formulation it asserts that for every bipartite graph $H$ and every graphon $W$,
\[
  t(H, W) \;\ge\; t(K_2, W)^{e(H)},
\]
where $t(H,W)$ is the homomorphism density of $H$ in $W$ and $e(H)$ is the number of edges
of $H$. Equivalently, among all graphons of a given edge density the constant (quasirandom)
graphon minimizes the number of copies of any bipartite pattern. The conjecture is known in
many special cases and open in general.

This paper isolates a structural mechanism behind inequalities of this type. We work in the
discrete, uniform-measure model: a \emph{weighted graph} on a finite vertex set $\iota$ is a
symmetric matrix $A \in \R^{\iota\times\iota}$. For cycles $C_k$ the relevant densities admit
clean spectral descriptions, and the tensor product of matrices provides a product operation
under which those densities are multiplicative. The multiplicativity converts qualitative
statements about the Sidorenko inequality into statements about a one-dimensional
multiplicative dynamical system.

Our contributions are: (1) \emph{spectral transfer} (Section~\ref{sec:transfer});
(2) \emph{Transfer Principle~I}, structural closure (Section~\ref{sec:principles});
(3) \emph{Transfer Principle~II}, strict amplification with fixed-point structure $\{0,1\}$
(Section~\ref{sec:principles}); (4) sign-free \emph{analytic seeds} for $C_2$ and $C_4$
(Section~\ref{sec:seeds}); and (5) a resulting \emph{tensor-closed class}
(Section~\ref{sec:closed}).

\section{Definitions}

Throughout, $\iota$ and $\kappa$ denote finite vertex sets, and $N = |\iota|$.

\begin{definition}[Weighted graph]
A weighted graph on $\iota$ is a matrix $A \in \R^{\iota\times\iota}$. It is \emph{symmetric}
if $A_{ij} = A_{ji}$ for all $i,j$. We impose no sign condition unless stated.
\end{definition}

\begin{definition}[Densities]
The homomorphism count of a single edge $K_2$ is the total weight
$\homc(K_2, A) = \sum_{i}\sum_{j} A_{ij}$, with density $t(K_2, A) = \homc(K_2,A)/N^2$. The
homomorphism count of the $k$-cycle $C_k$ is the number of closed walks of length $k$,
$\homc(C_k, A) = \tr(A^k)$, with density $t(C_k, A) = \tr(A^k)/N^k$.
\end{definition}

\begin{definition}[Sidorenko property and ratio]
The weighted graph $A$ satisfies the \emph{Sidorenko property for $C_k$} if
$t(K_2, A)^k \le t(C_k, A)$. Its \emph{Sidorenko ratio} is
$R_k(A) = t(C_k, A)/t(K_2, A)^k$; the property is $R_k(A) \ge 1$ when $t(K_2,A)\neq 0$.
\end{definition}

\begin{definition}[Tensor product]
For $A \in \R^{\iota\times\iota}$ and $B \in \R^{\kappa\times\kappa}$, the tensor product
$A \otimes B \in \R^{(\iota\times\kappa)\times(\iota\times\kappa)}$ has entries
$(A\otimes B)_{(i,i'),(j,j')} = A_{ij}\,B_{i'j'}$. It has $N_A N_B$ vertices and is symmetric
whenever $A$ and $B$ are.
\end{definition}

\section{Spectral Transfer}\label{sec:transfer}

\begin{lemma}[Tensor power splits]\label{lem:power}
For all $k$, $(A\otimes B)^k = A^k \otimes B^k$.
\end{lemma}
\begin{proof}
Induction on $k$. The base case $k=0$ is $I_{\iota\times\kappa} = I_\iota \otimes I_\kappa$.
For the step, apply the mixed-product law $(A\otimes B)(C\otimes D) = (AC)\otimes(BD)$ with
the inductive hypothesis:
$(A\otimes B)^{k+1} = (A^k\otimes B^k)(A\otimes B) = A^{k+1}\otimes B^{k+1}$.
\end{proof}

\begin{theorem}[Spectral transfer]\label{thm:transfer}
For all $k$, $\tr\big((A\otimes B)^k\big) = \tr(A^k)\cdot\tr(B^k)$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:power} the left side is $\tr(A^k \otimes B^k)$, and the trace of a
Kronecker product factors as $\tr(X\otimes Y) = \tr(X)\,\tr(Y)$.
\end{proof}

\begin{lemma}[Edge count is multiplicative]\label{lem:edge}
$\homc(K_2, A\otimes B) = \homc(K_2, A)\cdot\homc(K_2, B)$.
\end{lemma}
\begin{proof}
The double sum over $\iota\times\kappa$ factors:
$\sum_{(i,i'),(j,j')} A_{ij}B_{i'j'} = \big(\sum_{i,j}A_{ij}\big)\big(\sum_{i',j'}B_{i'j'}\big)$.
\end{proof}

\begin{corollary}[Densities factor]\label{cor:densities}
Using $|\iota\times\kappa| = N_A N_B$,
$t(C_k, A\otimes B) = t(C_k,A)\,t(C_k,B)$ and $t(K_2, A\otimes B) = t(K_2,A)\,t(K_2,B)$.
\end{corollary}
\begin{proof}
Each density is a count divided by a power of the vertex count; both the counts
(Theorem~\ref{thm:transfer}, Lemma~\ref{lem:edge}) and the normalizations
$(N_AN_B)^k = N_A^k N_B^k$ are multiplicative, so the quotients multiply. No positivity is
needed.
\end{proof}

\begin{theorem}[Ratio is multiplicative]\label{thm:ratio}
$R_k(A\otimes B) = R_k(A)\cdot R_k(B)$.
\end{theorem}
\begin{proof}
Immediate from Corollary~\ref{cor:densities}:
$R_k(A\otimes B) = \frac{t(C_k,A)t(C_k,B)}{(t(K_2,A)t(K_2,B))^k} = R_k(A)R_k(B)$.
\end{proof}

\section{The Two Transfer Principles}\label{sec:principles}

\begin{theorem}[Transfer Principle I: closure]\label{thm:closure}
Suppose $A$ and $B$ satisfy the Sidorenko property for $C_k$, and $t(K_2,A)\ge 0$,
$t(K_2,B)\ge 0$. Then $A\otimes B$ satisfies the Sidorenko property for $C_k$.
\end{theorem}
\begin{proof}
By Corollary~\ref{cor:densities}, $t(K_2, A\otimes B)^k = t(K_2,A)^k\,t(K_2,B)^k$ and
$t(C_k, A\otimes B) = t(C_k,A)\,t(C_k,B)$. Multiplying $t(K_2,A)^k \le t(C_k,A)$ and
$t(K_2,B)^k \le t(C_k,B)$ (both sides nonnegative under the sign conditions) gives the
claim.
\end{proof}

\begin{theorem}[Closure for even cycles, sign-free]\label{thm:closureeven}
If $k$ is even and $A, B$ satisfy the Sidorenko property for $C_k$, then so does
$A\otimes B$---with no positivity hypothesis.
\end{theorem}
\begin{proof}
For even $k$, $t(K_2,\cdot)^k$ is an even power, hence automatically nonnegative, so the
hypotheses of Theorem~\ref{thm:closure} are free.
\end{proof}

\begin{theorem}[Ratio squares under self-tensoring]\label{thm:square}
$R_k(A\otimes A) = R_k(A)^2$.
\end{theorem}
\begin{proof}
Set $B = A$ in Theorem~\ref{thm:ratio}.
\end{proof}

\begin{corollary}[Transfer Principle II: amplification]\label{cor:amp}
If $R_k(A) > 1$ then $R_k(A) < R_k(A\otimes A)$; if $0 < R_k(A) < 1$ then
$R_k(A\otimes A) < R_k(A)$; and if $R_k(A) = 1$ then $R_k(A\otimes A) = 1$.
\end{corollary}
\begin{proof}
By Theorem~\ref{thm:square}, $R_k(A\otimes A) = R_k(A)^2$, and $x^2 > x$ for $x>1$,
$x^2 < x$ for $0<x<1$, $x^2 = x$ for $x\in\{0,1\}$.
\end{proof}

\begin{remark}
Iterated self-tensoring produces the orbit $R, R^2, R^4, \dots$. The squaring map on
$[0,\infty)$ has exactly the fixed points $0$ and $1$; it repels away from $1$ toward
$\infty$ above $1$ and attracts toward $0$ on $(0,1)$. Hence the Sidorenko inequality has no
stable almost-tight regime, and $R=1$ (the quasirandom, extremal case) is the unique
nontrivial equilibrium.
\end{remark}

\section{Analytic Seeds: the Even Cycles $C_2$ and $C_4$}\label{sec:seeds}

\begin{lemma}[Trace of the square]\label{lem:trsq}
For symmetric $A$, $\tr(A^2) = \sum_{i}\sum_{j} A_{ij}^2$.
\end{lemma}
\begin{proof}
$\tr(A^2) = \sum_i \sum_j A_{ij}A_{ji}$, and symmetry gives $A_{ji}=A_{ij}$.
\end{proof}

\begin{lemma}[Cauchy--Schwarz over ordered pairs]\label{lem:cs}
For any $A$, $\big(\sum_{i,j} A_{ij}\big)^2 \le N^2 \sum_{i,j} A_{ij}^2$.
\end{lemma}
\begin{proof}
Cauchy--Schwarz for the $N^2$-term family $\{A_{ij}\}$ against the all-ones family:
$\big(\sum_p f_p\big)^2 \le |P|\sum_p f_p^2$ with $|P| = N^2$.
\end{proof}

\begin{theorem}[Sidorenko for $C_2$]\label{thm:c2}
Every symmetric weighted graph satisfies $t(C_2, A) \ge t(K_2, A)^2$.
\end{theorem}
\begin{proof}
With $S=\sum_{i,j}A_{ij}$, Lemma~\ref{lem:trsq} gives $t(C_2,A) = (\sum A_{ij}^2)/N^2$ and
$t(K_2,A)^2 = S^2/N^4$. Clearing denominators, the claim is Lemma~\ref{lem:cs}. The empty
vertex set $N=0$ makes both sides $0$.
\end{proof}

\begin{lemma}[$A^2$ is symmetric]\label{lem:sqsym}
If $A$ is symmetric, so is $A^2$.
\end{lemma}
\begin{proof}
$(A^2)_{ij} = \sum_k A_{ik}A_{kj} = \sum_k A_{ki}A_{jk} = (A^2)_{ji}$.
\end{proof}

\begin{lemma}[Total weight of $A^2$]\label{lem:tot}
For symmetric $A$, $\sum_{i,j} (A^2)_{ij} = \sum_{k}\big(\sum_{i} A_{ik}\big)^2$.
\end{lemma}
\begin{proof}
$\sum_{i,j}(A^2)_{ij} = \sum_{i,j,k} A_{ik}A_{kj} = \sum_k (\sum_i A_{ik})(\sum_j A_{kj})$,
and symmetry turns $\sum_j A_{kj}$ into $\sum_j A_{jk} = \sum_i A_{ik}$.
\end{proof}

\begin{theorem}[Sidorenko for $C_4$]\label{thm:c4}
Every symmetric weighted graph satisfies $t(C_4, A) \ge t(K_2, A)^4$.
\end{theorem}
\begin{proof}
Let $S = \sum_{i,j}A_{ij}$, $T = \sum_{i,j}(A^2)_{ij}$, $\mathrm{Tr} = \tr(A^4)$. Since
$A^4 = (A^2)^2$ and $A^2$ is symmetric (Lemma~\ref{lem:sqsym}), Lemma~\ref{lem:trsq} gives
$\mathrm{Tr} = \sum_{i,j}((A^2)_{ij})^2$. Two Cauchy--Schwarz steps follow.
\emph{Step 1} (Lemma~\ref{lem:cs} for $A^2$): $T^2 \le N^2\,\mathrm{Tr}$. \emph{Step 2}
(Cauchy--Schwarz on the $N$ column sums, using Lemma~\ref{lem:tot}):
$T = \sum_k(\sum_i A_{ik})^2$ and $S = \sum_k\sum_i A_{ik}$, so $S^2 \le N\,T$ and $T\ge 0$.
Combining, $N^6 T^2 \le N^8\,\mathrm{Tr}$ and $N^4 S^4 = N^4(S^2)^2 \le N^4(NT)^2 = N^6 T^2$,
whence $N^4 S^4 \le N^8\,\mathrm{Tr}$, i.e. $t(K_2,A)^4 \le t(C_4,A)$.
\end{proof}

\begin{remark}[Sign-freeness and sharpness]
Neither proof inspects the sign of any entry: the intermediate quantities are sums of
squares, hence automatically nonnegative. The usual nonnegativity hypothesis on graphons is
unnecessary for even cycles. Both inequalities are sharp (constant weightings give equality),
and odd cycles are genuinely excluded, matching the bipartite restriction of the conjecture.
\end{remark}

\section{A Tensor-Closed Class}\label{sec:closed}

\begin{theorem}[Closure of the $C_4$-Sidorenko class]\label{thm:c4closed}
If $A$ and $B$ are symmetric weighted graphs, then $A\otimes B$ satisfies
$t(C_4, A\otimes B) \ge t(K_2, A\otimes B)^4$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:c4} both $A$ and $B$ satisfy $C_4$-Sidorenko, and $A\otimes B$ is
symmetric. Since $4$ is even, Theorem~\ref{thm:closureeven} applies with no positivity
hypothesis.
\end{proof}

Starting from the seeds of Section~\ref{sec:seeds} and applying Theorem~\ref{thm:c4closed}
(and its iterates), one obtains an entire tensor-closed family of symmetric weighted graphs
all satisfying the even-cycle Sidorenko inequality, with no sign restriction anywhere.

\section{Discussion and Future Work}

The results separate the framework into an \emph{algebraic engine} (spectral transfer and the
two transfer principles) and an \emph{analytic seed layer} (the Cauchy--Schwarz base cases).
Three directions stand out. (1) \emph{Sign-free even-cycle Sidorenko for all lengths}: the
$C_4$ proof exposes a recursive doubling $A^r\mapsto A^{2r}$ via a single Cauchy--Schwarz
step; an induction on $m$ would yield $t(C_{2m},A)\ge t(K_2,A)^{2m}$ for all symmetric
weighted graphs. (2) \emph{The ratio spectrum}: characterize the realizable ratios and prove
the multiplicative closure of the achievable set is $[0,\infty)$. (3) \emph{Spectral transfer
beyond cycles}: the multiplicativity $t(H,A\otimes B)=t(H,A)\,t(H,B)$ is expected for every
pattern $H$, extending both transfer principles to arbitrary bipartite patterns.

