"""Density evaluator for weighted graphs (edge and cycle densities)."""
from __future__ import annotations
from typing import List

Matrix = List[List[float]]

def mat_mul(A: Matrix, B: Matrix) -> Matrix:
    n = len(A)
    return [[sum(A[i][k] * B[k][j] for k in range(n)) for j in range(n)] for i in range(n)]

def mat_pow(A: Matrix, k: int) -> Matrix:
    n = len(A)
    R: Matrix = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    B = [row[:] for row in A]
    while k:
        if k & 1:
            R = mat_mul(R, B)
        B = mat_mul(B, B)
        k >>= 1
    return R

def t_edge(A: Matrix) -> float:
    n = len(A)
    return sum(sum(r) for r in A) / n ** 2

def t_cycle(k: int, A: Matrix) -> float:
    n = len(A)
    P = mat_pow(A, k)
    return sum(P[i][i] for i in range(n)) / n ** k

def sid_ratio(k: int, A: Matrix) -> float:
    return t_cycle(k, A) / t_edge(A) ** k

if __name__ == "__main__":
    A = [[0.3, 0.7, 0.2], [0.7, 0.5, 0.9], [0.2, 0.9, 0.4]]
    for k in (2, 4, 6):
        print(f"k={k}: t(Ck)={t_cycle(k, A):.5f}  t(K2)^k={t_edge(A)**k:.5f}  R={sid_ratio(k, A):.5f}")

"""Sign-free base cases: C2 and C4 Sidorenko hold even for signed symmetric graphs."""
from __future__ import annotations
import random
from typing import List

Matrix = List[List[float]]

def random_symmetric(n: int, signed: bool = True) -> Matrix:
    A: Matrix = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            v = random.uniform(-2, 2) if signed else random.uniform(0, 2)
            A[i][j] = A[j][i] = v
    return A

def mat_mul(A: Matrix, B: Matrix) -> Matrix:
    n = len(A)
    return [[sum(A[i][k] * B[k][j] for k in range(n)) for j in range(n)] for i in range(n)]

def trace(A: Matrix) -> float:
    return sum(A[i][i] for i in range(len(A)))

def t_edge(A: Matrix) -> float:
    n = len(A)
    return sum(sum(r) for r in A) / n ** 2

def t_cycle_even(m: int, A: Matrix) -> float:
    n = len(A); P = [row[:] for row in A]
    for _ in range(m - 1):
        P = mat_mul(P, A)
    return trace(P) / n ** m

if __name__ == "__main__":
    random.seed(0)
    worst2 = worst4 = float("inf")
    for _ in range(20000):
        A = random_symmetric(random.randint(1, 4), signed=True)
        r2 = t_cycle_even(2, A) - t_edge(A) ** 2
        r4 = t_cycle_even(4, A) - t_edge(A) ** 4
        worst2 = min(worst2, r2); worst4 = min(worst4, r4)
    print(f"min (t(C2)-t(K2)^2) over 20000 signed graphs = {worst2:.3e}  (>= 0 confirms Sidorenko)")
    print(f"min (t(C4)-t(K2)^4) over 20000 signed graphs = {worst4:.3e}  (>= 0 confirms Sidorenko)")

"""Spectral transfer: verify t(Ck, A (x) B) = t(Ck, A) * t(Ck, B) numerically."""
from __future__ import annotations
import random
from typing import List

Matrix = List[List[float]]

def mat_mul(A: Matrix, B: Matrix) -> Matrix:
    n = len(A)
    return [[sum(A[i][k] * B[k][j] for k in range(n)) for j in range(n)] for i in range(n)]

def mat_pow(A: Matrix, k: int) -> Matrix:
    n = len(A); R = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]; B = [r[:] for r in A]
    while k:
        if k & 1: R = mat_mul(R, B)
        B = mat_mul(B, B); k >>= 1
    return R

def t_cycle(k: int, A: Matrix) -> float:
    n = len(A); P = mat_pow(A, k)
    return sum(P[i][i] for i in range(n)) / n ** k

def kron(A: Matrix, B: Matrix) -> Matrix:
    na, nb = len(A), len(B); n = na * nb
    C = [[0.0] * n for _ in range(n)]
    for i in range(na):
        for j in range(na):
            for ip in range(nb):
                for jp in range(nb):
                    C[i * nb + ip][j * nb + jp] = A[i][j] * B[ip][jp]
    return C

if __name__ == "__main__":
    random.seed(1)
    A = [[random.uniform(-1, 1) for _ in range(2)] for _ in range(2)]
    A = [[A[0][0], A[0][1]], [A[0][1], A[1][1]]]
    B = [[random.uniform(-1, 1) for _ in range(3)] for _ in range(3)]
    for i in range(3):
        for j in range(3):
            B[j][i] = B[i][j]
    AB = kron(A, B)
    for k in (2, 4, 6):
        lhs, rhs = t_cycle(k, AB), t_cycle(k, A) * t_cycle(k, B)
        print(f"k={k}: t(Ck,A(x)B)={lhs:+.6f}  product={rhs:+.6f}  err={abs(lhs-rhs):.1e}")

